question:
Using C with <string.h> included, what does LocateElem(e) return when e answers: On January 1, 2020, did New Zealand grant citizenship solely from a child's and one parent's births there, irrespective of parental citizenship?

const char *L[] = {"Yes", "No"};
int LocateElem(const char *e) {
    int p = 0;
    while (p < 2 && strcmp(L[p++], e) != 0) {}
    return p;
}
